            let response = self
                .http
                .post(&self.url)
                .bearer_auth(&self.token)
                .header(reqwest::header::CONTENT_TYPE, "text/plain")
                .header(reqwest::header::ACCEPT, "application/json, application/x-ndjson")
                .header(reqwest::header::USER_AGENT, self.user_agent.clone())
                .body(body.to_string())
                .send()
                .await?;
